using System.Diagnostics;
namespace Charker;
public sealed class MatterBridge : IDisposable {
 Process? process;TaskCompletionSource<object>? ready;readonly object gate=new();public object Status {get;private set;}=new{status="stopped"};public event Action<object>? Message;public Func<int,bool,Task>? Control {get;set;}
 public async Task Start(string model,string dataRoot){Dispose();string dir=Path.Combine(AppContext.BaseDirectory,"Bridge");string node=Path.Combine(dir,"node.exe");if(!File.Exists(node))throw new IOException("Matter 运行库缺失，请保留完整程序文件夹。");ready=new(TaskCreationOptions.RunContinuationsAsynchronously);var start=new ProcessStartInfo(node){WorkingDirectory=dir,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add(Path.Combine(dir,"bridge.mjs"));start.ArgumentList.Add(Path.Combine(dataRoot,"Matter"));start.ArgumentList.Add(model);process=new(){StartInfo=start,EnableRaisingEvents=true};process.OutputDataReceived+=async(_,e)=>{if(e.Data==null)return;try{var m=JsonNode.Parse(e.Data)!.AsObject();switch(m["type"]?.ToString()){case "ready":Status=m;ready?.TrySetResult(m);Message?.Invoke(m);break;case "error":Status=new{status="error",error=m["error"]?.ToString()};ready?.TrySetException(new IOException(m["error"]?.ToString()));Message?.Invoke(Status);break;case "control":int p=(int)m["port"]!;bool on=(bool)m["on"]!;try{if(Control!=null)await Control(p,on);else throw new IOException("端口控制不可用");Send(new{type="result",id=m["id"]!.ToString(),ok=true});}catch(Exception ex){Send(new{type="result",id=m["id"]!.ToString(),ok=false,error=ex.Message});}break;}}catch(JsonException){}};
  process.ErrorDataReceived+=(_,e)=>{};process.Exited+=(_,_)=>{ready?.TrySetException(new IOException("Matter 进程已退出。"));};process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();try{await ready.Task.WaitAsync(TimeSpan.FromSeconds(60));}catch{Dispose();throw;}
 }
 void Send(object o){lock(gate){try{if(process is {HasExited:false}){process.StandardInput.WriteLine(JsonSerializer.Serialize(o,Store.Json));process.StandardInput.Flush();}}catch(IOException){}}}
 public void Update(DeviceState s,bool allow)=>Send(new{type="update",device=s,allow});
 public void Dispose(){var p=process;if(p==null){Status=new{status="stopped"};return;}Send(new{type="stop"});process=null;_=Task.Run(()=>{try{if(!p.WaitForExit(5000))p.Kill(true);}catch{}finally{p.Dispose();}});Status=new{status="stopped"};Message?.Invoke(Status);}
}
